-- AVORA-100 · S.2 §4.4 C — the open-licence (CC BY 4.0) Vietnamese picture books listed by the Global
-- Digital Library content API on 11/10/2026, with the contributors named in each book's official EPUB.
-- Generated from `/wp-json/content-api/v1/books/vi` + `/wp-json/epub-generator/v1/book/{id}`; NC licences left out.
on conflict (source, source_id) do update set
  title = excluded.title, title_vi = excluded.title_vi, authors = excluded.authors, credits = excluded.credits,
  category = excluded.category, pd_status = excluded.pd_status, access = excluded.access, updated_at = now();

-- Attribution names the author: books whose EPUB names nobody are left out rather than credited vaguely.
delete from public.book_catalog where source = 'gdl' and jsonb_array_length(coalesce(credits -> 'authors', '[]'::jsonb)) = 0;
